/* ── Estilos ── */
(function(){
  var css = [
    /* ── Botón principal sustitutos ── */
    ".imod-sust-btn {",
    "  display:inline-flex; align-items:center; gap:6px;",
    "  margin:6px 16px 0; padding:7px 14px;",
    "  background:rgba(232,25,44,.1); border:1px solid rgba(232,25,44,.5);",
    "  border-radius:8px; cursor:pointer;",
    "  font-family:'Rajdhani',sans-serif; font-size:12px; font-weight:700;",
    "  letter-spacing:1px; color:#E8192C; text-transform:uppercase;",
    "  transition:all .2s; width:calc(100% - 32px); justify-content:center;",
    "}",
    ".imod-sust-btn:hover { background:rgba(232,25,44,.2); border-color:#E8192C; color:#fff; }",
    ".imod-sust-btn .sust-count-badge {",
    "  background:#E8192C; color:#fff; border-radius:10px;",
    "  font-size:10px; padding:1px 7px; font-weight:700;",
    "}",
    /* ── Panel tabla ── */
    ".imod-sust-panel { margin:0 16px 12px; display:none; }",
    ".imod-sust-panel.open { display:block; }",
    ".imod-sust-table { width:100%; border-collapse:collapse; font-size:11px; }",
    ".imod-sust-table thead tr { background:rgba(232,25,44,.15); }",
    ".imod-sust-table th {",
    "  padding:6px 8px; text-align:left;",
    "  font-family:'Rajdhani',sans-serif; font-weight:700; letter-spacing:1px;",
    "  color:#E8192C; font-size:10px; text-transform:uppercase;",
    "  border-bottom:1px solid rgba(232,25,44,.3);",
    "}",
    ".imod-sust-table td {",
    "  padding:6px 8px; border-bottom:1px solid rgba(255,255,255,.05);",
    "  color:#c8d0e4; font-size:10px; vertical-align:middle;",
    "}",
    ".imod-sust-table tbody tr:hover td { background:rgba(232,25,44,.06); }",
    /* ── Miniatura ── */
    ".sust-img-cell { width:48px; padding:3px 6px !important; }",
    ".sust-thumb {",
    "  width:44px; height:44px; border-radius:6px;",
    "  border:1px solid #2a2a45; background:#0d0d1e;",
    "  object-fit:contain; display:block;",
    "  transition:border-color .15s, transform .15s; cursor:pointer;",
    "}",
    ".imod-sust-table tbody tr:hover .sust-thumb { border-color:#E8192C; transform:scale(1.06); }",
    ".sust-thumb-placeholder {",
    "  width:44px; height:44px; border-radius:6px; border:1px solid #2a2a45;",
    "  background:#0d0d1e; display:flex; align-items:center; justify-content:center;",
    "  font-size:18px; opacity:.35;",
    "}",
    /* ── Código ── */
    ".sust-code-link {",
    "  font-family:'Rajdhani',sans-serif; font-size:15px; font-weight:700;",
    "  color:#E8192C; cursor:pointer; background:none; border:none; padding:0;",
    "  text-decoration:underline dotted; transition:color .15s; display:block;",
    "  white-space:nowrap;",
    "}",
    ".sust-code-link:hover { color:#fff; }",
    ".sust-desc-cell { font-size:9.5px; line-height:1.35; text-transform:uppercase; letter-spacing:.2px; }",
    /* ── Botón carrito en fila sustituto ── */
    ".sust-cart-cell { width:34px; padding:3px 4px !important; text-align:center; }",
    ".sust-add-btn {",
    "  width:28px; height:28px; border-radius:50%;",
    "  background:rgba(0,212,255,.15); border:2px solid #00D4FF;",
    "  color:#00D4FF;",
    "  font-family:'Rajdhani',sans-serif; font-size:18px; font-weight:700; line-height:1;",
    "  cursor:pointer; display:flex; align-items:center; justify-content:center;",
    "  transition:all .18s; box-shadow:0 2px 8px rgba(0,0,0,.5);",
    "  flex-shrink:0;",
    "}",
    ".sust-add-btn:hover { background:#00D4FF; color:#000; transform:scale(1.12); box-shadow:0 0 12px rgba(0,212,255,.6); }",
    ".sust-add-btn.in-cart { background:#22c55e; color:#fff; border-color:#22c55e; font-size:13px; }",
    ".sust-add-btn.in-cart:hover { background:#16a34a; border-color:#16a34a; }",
    /* ── Referencias ocultas ── */
    ".sust-hidden-refs { display:none !important; }"
  ].join('\n');
  var s = document.createElement('style');
  s.textContent = css;
  document.head.appendChild(s);
})();

/* ── Patch matchQuery: incluir refs ocultas en búsqueda ── */
(function(){
  var _orig = window.matchQuery;
  if (!_orig) return;
  window.matchQuery = function(p, q) {
    if (!q) return true;
    var tokens = q.toLowerCase().split(/\s+/).filter(Boolean);
    if (!tokens.length) return true;
    var sustRefs = '';
    var susts = SUST_DB[String(p[0])];
    if (susts) {
      susts.forEach(function(s) {
        if (s.r) sustRefs += ' ' + s.r.join(' ');
      });
    }
    var pvText = (window.PV_TEXT_INDEX && window.PV_TEXT_INDEX[p[0]]) || '';
    var haystack = [
      p[0],
      p[1] ? p[1].toLowerCase() : '',
      p[2] ? p[2].toLowerCase() : '',
      p[3] ? p[3].toLowerCase() : '',
      p[4] ? p[4].toLowerCase() : '',
      p[5] ? p[5].toLowerCase() : '',
      p[6] ? p[6].toLowerCase() : '',
      pvText,
      sustRefs.toLowerCase()
    ].join(' ');
    return tokens.every(function(t) { return haystack.indexOf(t) >= 0; });
  };
})();

/* ── Patch openImgModal ── */
(function(){
  var _orig = window.openImgModal;
  if (!_orig) return;
  window.openImgModal = function(e, code, name) {
    _orig.call(this, e, code, name);
    setTimeout(function() { injectSustUI(code); }, 0);
  };
})();

function sustImgUrl(code) {
  return 'https://resources.apymsa.com.mx/imagenes/FotosSpeed/' + code + '/' + code + '2a.jpg';
}

function injectSustUI(code) {
  var old = document.getElementById('sust-btn-wrap');
  if (old) old.remove();
  var oldPanel = document.getElementById('sust-panel');
  if (oldPanel) oldPanel.remove();

  var susts = SUST_DB[String(code)];
  if (!susts || !susts.length) return;

  /* Deduplicar por código */
  var byCode = {};
  susts.forEach(function(s) {
    if (!byCode[s.c]) byCode[s.c] = { c: s.c, d: s.d, r: s.r || [] };
    else {
      (s.r || []).forEach(function(r) {
        if (byCode[s.c].r.indexOf(r) < 0) byCode[s.c].r.push(r);
      });
    }
  });
  var list = Object.values(byCode);

  /* --- BOTÓN TOGGLE --- */
  var btnWrap = document.createElement('div');
  btnWrap.id = 'sust-btn-wrap';
  var btn = document.createElement('button');
  btn.className = 'imod-sust-btn';
  btn.innerHTML = '🔄 Productos Sustitutos <span class="sust-count-badge">' + list.length + '</span>';
  btn.onclick = function() { toggleSustPanel(); };
  btnWrap.appendChild(btn);

  /* --- PANEL --- */
  var panel = document.createElement('div');
  panel.className = 'imod-sust-panel';
  panel.id = 'sust-panel';

  var rows = list.map(function(s) {
    var imgUrl = sustImgUrl(s.c);
    var refsHidden = s.r.length
      ? '<span class="sust-hidden-refs" aria-hidden="true">' + s.r.map(escH).join(' ') + '</span>'
      : '';
    var isInCart = window.cart && window.cart.some(function(it) { return it.code === s.c; });
    var cartClass = isInCart ? ' in-cart' : '';
    var cartLabel = isInCart ? '&#10003;' : '+';

    return '<tr>'
      /* imagen */
      + '<td class="sust-img-cell" onclick="openSustProduct(\'' + escH(s.c) + '\')" style="cursor:pointer">'
      +   '<img class="sust-thumb" src="' + imgUrl + '" alt="' + escH(s.c) + '" referrerpolicy="no-referrer" data-sust-img="1">'
      +   '<div class="sust-thumb-placeholder" style="display:none">&#128230;</div>'
      + '</td>'
      /* código */
      + '<td onclick="openSustProduct(\'' + escH(s.c) + '\')" style="cursor:pointer">'
      +   '<button class="sust-code-link">' + escH(s.c) + '</button>'
      +   refsHidden
      + '</td>'
      /* descripción */
      + '<td class="sust-desc-cell" onclick="openSustProduct(\'' + escH(s.c) + '\')" style="cursor:pointer">'
      +   escH(s.d)
      + '</td>'
      /* botón carrito */
      + '<td class="sust-cart-cell">'
      +   '<button class="sust-add-btn' + cartClass + '" data-cart-btn="' + escH(s.c) + '"'
      +   ' onclick="sustCartAdd(\'' + escH(s.c) + '\',event)" title="Agregar al carrito">'
      +   cartLabel
      + '</button>'
      + '</td>'
      + '</tr>';
  }).join('');

  panel.innerHTML = '<table class="imod-sust-table">'
    + '<thead><tr><th></th><th>Código</th><th>Descripción</th><th></th></tr></thead>'
    + '<tbody>' + rows + '</tbody>'
    + '</table>';

  /* Fallback imágenes rotas */
  setTimeout(function() {
    panel.querySelectorAll('img[data-sust-img]').forEach(function(img) {
      img.onerror = function() {
        this.style.display = 'none';
        var ph = this.nextElementSibling;
        if (ph) ph.style.display = 'flex';
      };
    });
  }, 10);

  var pvSection = document.getElementById('imod-pv-section');
  if (pvSection) {
    pvSection.parentNode.insertBefore(btnWrap, pvSection);
    pvSection.parentNode.insertBefore(panel, pvSection);
  } else {
    var imodRight = document.querySelector('.imod-right');
    if (imodRight) {
      imodRight.insertBefore(panel, imodRight.firstChild);
      imodRight.insertBefore(btnWrap, imodRight.firstChild);
    }
  }
}

function toggleSustPanel() {
  var panel = document.getElementById('sust-panel');
  var btn = document.querySelector('.imod-sust-btn');
  if (!panel) return;
  var open = panel.classList.toggle('open');
  var count = panel.querySelectorAll('tbody tr').length;
  if (btn) {
    btn.innerHTML = (open ? '🔄 Ocultar Sustitutos' : '🔄 Productos Sustitutos')
      + ' <span class="sust-count-badge">' + count + '</span>';
  }
}

/* Agregar sustituto al carrito y actualizar el botón de la fila */
function sustCartAdd(code, ev) {
  if (ev) { ev.preventDefault(); ev.stopPropagation(); }
  if (typeof window.cartAdd === 'function') {
    window.cartAdd(code, ev);
  }
  /* Actualizar todos los botones con ese código (incluido el de la fila) */
  setTimeout(function() {
    document.querySelectorAll('[data-cart-btn="' + code + '"]').forEach(function(b) {
      var inCart = window.cart && window.cart.some(function(it) { return it.code === code; });
      b.classList.toggle('in-cart', inCart);
      b.innerHTML = inCart ? '&#10003;' : '+';
    });
  }, 50);
}

function openSustProduct(code) {
  var product = null;
  if (window.P) {
    for (var i = 0; i < P.length; i++) {
      if (String(P[i][0]) === String(code)) { product = P[i]; break; }
    }
  }
  if (product) {
    var safeName = (product[1] || '').substring(0, 60).replace(/'/g, '&#39;');
    openImgModal({ preventDefault: function(){}, stopPropagation: function(){} }, code, safeName);
  } else {
    alert('Producto ' + code + ' no disponible en este catálogo.');
  }
}

function escH(s) {
  return String(s)
    .replace(/&/g,'&amp;')
    .replace(/</g,'&lt;')
    .replace(/>/g,'&gt;')
    .replace(/"/g,'&quot;')
    .replace(/'/g,'&#39;');
}
